<script setup lang="ts">import {computed} from 'vue';import type {Workbench} from '../app/useWorkbench';import RunStage from './RunStage.vue';const {w}=defineProps<{w:Workbench}>();const s=w.s;const runs=computed(()=>{const rows=s.history.runs||s.history.items||s.history.records||[];return rows.filter((r:any)=>(!s.historyFilter||(r.verdict||r.result?.verdict)===s.historyFilter)&&(!s.historyFunction||(r.context?.func||r.func)===s.historyFunction));});const verdicts:Record<string,string>={success:'成功',partial:'部分成功',no_update:'无模型更新',unconfirmed:'未确认',failed:'失败',cancelled:'已取消',pending:'处理中'};function date(v:any){if(!v)return '未记录';return new Date(typeof v==='number'?v*1000:v).toLocaleString('zh-CN');}</script>
<template><div class="page-heading"><div><div class="eyebrow">RUN HISTORY</div><h1>运行记录</h1><p>查看固定会话、完整日志与归档，不改变正在运行的任务。</p></div><el-button @click="w.run('刷新运行记录',()=>w.loadHistory(s.history.offset||0))">刷新记录</el-button></div><section class="card" data-testid="history"><div class="editor-toolbar"><el-select v-model="s.historyFunction" clearable placeholder="全部功能"><el-option v-for="f in s.state.functions" :key="f" :value="f" :label="f"/></el-select><el-select v-model="s.historyFilter" clearable placeholder="全部状态"><el-option v-for="(label,value) in verdicts" :key="value" :value="value" :label="label"/></el-select><span class="muted">当前项目 · 共 {{s.history.total||0}} 条记录</span></div><el-table :data="runs" empty-text="当前项目没有符合筛选的运行记录" @row-click="(row:any)=>w.selectHistory(row.sid)"><el-table-column prop="sid" label="会话" width="100"/><el-table-column label="任务与功能" min-width="220"><template #default="{row}"><strong>{{row.context?.task_name||row.task_name||row.label||row.schema||'工具任务'}}</strong><small class="block">{{row.context?.func||row.func||row.context?.operation||'—'}}</small></template></el-table-column><el-table-column label="时间" min-width="185"><template #default="{row}">{{date(row.started_at||row.started||row.start_time||row.created_at)}}</template></el-table-column><el-table-column label="当时结论" width="140"><template #default="{row}"><el-tag :type="(row.verdict||row.result?.verdict)==='success'?'success':(row.verdict||row.result?.verdict)==='failed'?'danger':'warning'">{{verdicts[row.verdict||row.result?.verdict]||row.status||'未确认'}}</el-tag></template></el-table-column><el-table-column width="110"><template #default="{row}"><el-button text type="primary" @click.stop="w.selectHistory(row.sid)">查看会话</el-button></template></el-table-column></el-table><div class="history-pagination"><el-pagination layout="prev,pager,next,total" :page-size="20" :total="s.history.total||0" :current-page="Math.floor((s.history.offset||0)/20)+1" @current-change="(page:number)=>w.run('读取运行记录',()=>w.loadHistory((page-1)*20))"/></div></section><RunStage v-if="s.result&&s.logHistorical" :w="w"/></template>
